const input = $input.first();
const body = input.json.body || input.json;
const projectId = String(body.project_id || '').replace(/[^a-zA-Z0-9_-]/g, '');
const subPath = String(body.path || '').replace(/\.\./g, '').replace(/^\//,'');

if (!projectId || !subPath) {
  throw new Error('project_id en path zijn verplicht.');
}

const basePath = '/home/node/n8n-files/projects';
const targetDir = `${basePath}/${projectId}/${subPath}`;

// Geef binary data door met het doelpad
const binaryKeys = Object.keys(input.binary || {});
const items = [];

for (const key of binaryKeys) {
  const binaryData = input.binary[key];
  const fileName = (binaryData.fileName || `upload_${Date.now()}`).replace(/[^a-zA-Z0-9._-]/g, '_');

  items.push({
    json: {
      targetDir,
      fileName,
      fullPath: `${targetDir}/${fileName}`
    },
    binary: {
      data: input.binary[key]
    }
  });
}

if (items.length === 0) {
  throw new Error('Geen bestanden ontvangen.');
}

return items;

const items = $input.all();
const saved = items.map(i => i.json.fileName || 'unknown');
return [{
  json: {
    success: true,
    message: `${saved.length} bestand(en) opgeslagen.`,
    files: saved
  }
}];
